$('swapOneFive').onclick=()=>{state.countShift=((state.countShift||0)+4)%8;lastBeat=-Infinity;lastSub=-1;resetAudioSchedule();renderEvents();save();status('Se intercambiaron 1 y 5 del ciclo de baile. Los tiempos de los pulsos del audio se conservaron.')};
$('tap').onclick=()=>{const n=performance.now();if(taps.length&&n-taps.at(-1)>2000)taps=[];taps.push(n);taps=taps.slice(-9);if(taps.length>2){const spans=taps.slice(1).map((v,i)=>v-taps[i]).sort((a,b)=>a-b);const bpm=60000/spans[Math.floor(spans.length/2)];if(bpm>=40&&bpm<=300){state.beatTimes=[];state.analyzedRange=null;state.bpm=Math.round(bpm*10)/10;$('bpm').value=state.bpm;renderEvents();save()}}status(`Tap ${taps.length}: pulsa una vez por pulso. ${taps.length>2?state.bpm+' BPM; marca después el primer 1.':'Haz al menos 3 pulsaciones.'}`)};
$('rate').onchange=()=>{if(state.mode==='demo'){if(state.playing)baseTime=Math.min(state.duration,baseTime+(clockMs()-baseAt)/1000*previousRate);baseAt=clockMs()}else if(state.mode==='youtube'){if(ytReady)yt.setPlaybackRate(+$('rate').value)}else if(media)media.playbackRate=+$('rate').value;previousRate=+$('rate').value};

$('now').onclick=()=>{$('markTime').value=current().toFixed(2)};$('markForm').onsubmit=e=>{e.preventDefault();const time=+$('markTime').value,name=$('markName').value.trim();if(!name||time<0||time>state.duration){status('La marca necesita un nombre y un tiempo dentro de la canción.');return}state.events.push({time,name,type:$('markType').value});$('markName').value='';renderEvents();save();status('Marca agregada. Puedes saltar a ella pulsando su tiempo.')} ;
$('export').onclick=()=>{save();const blob=new Blob([localStorage.getItem(storageKey)||'{}'],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='compas-mapa.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)};
function validateMap(data){if(data.version!==1||!Number.isFinite(data.bpm)||data.bpm<40||data.bpm>300||!Number.isFinite(data.offset)||data.offset<0||!Array.isArray(data.events)||data.events.length>1000)throw Error('Mapa inválido');if(data.beatTimes!==undefined&&(!Array.isArray(data.beatTimes)||data.beatTimes.length>20000||data.beatTimes.some((t,i)=>!Number.isFinite(t)||t<0||(i>0&&t<=data.beatTimes[i-1]))))throw Error('Pulsos inválidos');return data.events.map(e=>{if(!Number.isFinite(e.time)||e.time<0||typeof e.name!=='string'||e.name.length>80||!['Instrumento','Voz','Sección','Acento'].includes(e.type))throw Error('Marca inválida');return{time:e.time,name:e.name,type:e.type,auto:!!e.auto}})}
$('import').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>1e6)throw Error('Mapa demasiado grande');const data=JSON.parse(await f.text()),events=validateMap(data);if(events.some(e=>e.time>state.duration)||data.offset>=state.duration)throw Error('Carga primero la canción correspondiente: hay marcas fuera de su duración');if(data.beatTimes?.some(t=>t>state.duration))throw Error('Los pulsos no corresponden a esta duración');state.analysisEngine=typeof data.analysisEngine==='string'?data.analysisEngine.slice(0,100):null;state.downbeats=Array.isArray(data.downbeats)?data.downbeats.filter(t=>Number.isFinite(t)&&t>=0&&t<=state.duration).slice(0,20000):[];state.countShift=Number.isInteger(data.countShift)?((data.countShift%8)+8)%8:0;state.events=events;state.diagnostics=Array.isArray(data.diagnostics)?data.diagnostics.filter(a=>Number.isFinite(a.start)&&Number.isFinite(a.end)&&a.start>=0&&a.end>a.start&&a.end<=state.duration&&typeof a.label==='string'&&a.label.length<120).slice(0,80):[];state.beatTimes=data.beatTimes||[];state.analyzedRange=data.analyzedRange&&Number.isFinite(data.analyzedRange.start)&&Number.isFinite(data.analyzedRange.end)&&data.analyzedRange.start>=0&&data.analyzedRange.end>data.analyzedRange.start?data.analyzedRange:null;state.aligned=true;state.bpm=data.bpm;state.offset=data.offset;$('bpm').value=data.bpm;$('offset').value=data.offset;if(['on1','on2'].includes(data.style))$('style').value=data.style;if(['23','32'].includes(data.clave))$('clave').value=data.clave;buildCounts();buildGrid();renderEvents();save();status('Mapa abierto sobre la música actual. Verifica que corresponda a la misma grabación.')}catch(err){status('No se pudo abrir el mapa: '+err.message)}e.target.value=''};
document.addEventListener('keydown',e=>{if(e.code==='Space'&&!['INPUT','SELECT','BUTTON','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();$('play').click()}});window.addEventListener('resize',drawWave);document.addEventListener('visibilitychange',()=>{if(document.hidden&&state.playing)pause()});
try{const timing=localStorage.getItem('compas-timing');if(['on1','on2'].includes(timing))$('style').value=timing}catch{}
buildCounts();buildGrid();renderEvents();update();function paintFrame(){update();requestAnimationFrame(paintFrame)}requestAnimationFrame(paintFrame);

